#!/usr/bin/env bash
# Kredilo - in-app "What's New" announcement: a one-time modal for every signed-in user
# (new signups see it after the welcome walkthrough), a "Try new games" button, and a
# built-in one-week time limit. Ships the announcement image too. Run from the repo root:
#   cd ~/kredilo && bash apply-kredilo-whatsnew.sh
set -euo pipefail
if [ ! -f package.json ] || [ ! -d src ] || [ ! -d server ]; then
  echo "Run this from the kredilo repo root (where package.json, src/ and server/ live)." >&2
  exit 1
fi
echo "Writing files..."
mkdir -p "public"
base64 -d > "public/whats-new.jpg" <<'KREDILO_IMG_EOF'
